const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([100.141422, 20.248364]);
  const date1 = '2015-01-27';
  const date2 = '2020-01-25';

  // Create date ranges (±3 days for flexibility)
  const start1 = '2015-01-24';
  const end1 = '2015-01-30';
  const start2 = '2020-01-22';
  const end2 = '2020-01-28';

  // 2. Data Acquisition for 2015 (Landsat 8)
  let col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(point)
    .filterDate(start1, end1)
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size1 = col1.size().getInfo();
  console.log(`2015 Images found: ${size1}`);

  if (size1 === 0) {
    console.log("No data for 2015.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Data Acquisition for 2020 (Try Sentinel-2 first, then Landsat 8)
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(point)
    .filterDate(start2, end2)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let size2 = col2.size().getInfo();
  console.log(`2020 Sentinel-2 Images found: ${size2}`);

  if (size2 === 0) {
    console.log("Trying Landsat 8 for 2020...");
    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(point)
      .filterDate(start2, end2)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
    size2 = col2.size().getInfo();
    console.log(`2020 Landsat 8 Images found: ${size2}`);
  }

  if (size2 === 0) {
    console.log("No data for 2020.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Process 2015 data (Landsat 8)
  function maskL8clouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask)
      .select(['SR_B4', 'SR_B5'])
      .multiply(0.0000275).add(-0.2);
  }

  const img1 = col1.map(maskL8clouds).median();

  // Calculate turbidity proxy (Red band is good for sediment)
  const turbidity1Result = img1.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 3000,
    maxPixels: 1e9
  });

  const count1 = img1.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: 3000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  console.log(`2015 Valid pixels: ${count1}`);

  if (count1 === 0) {
    console.log("No valid pixels for 2015 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  const turbidity1 = turbidity1Result.get('SR_B4').getInfo();

  // 5. Process 2020 data
  let img2, turbidity2, count2;

  if (col2.first().bandNames().getInfo().includes('B4')) {
    // Sentinel-2
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
        .and(qa.bitwiseAnd(1 << 11).eq(0));
      return image.updateMask(cloudMask)
        .select(['B4', 'B8'])
        .multiply(0.0001);
    }

    img2 = col2.map(maskS2clouds).median();

    const turbidity2Result = img2.select('B4').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: point,
      scale: 3000,
      maxPixels: 1e9
    });

    count2 = img2.select('B4').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: point,
      scale: 3000,
      maxPixels: 1e9
    }).get('B4').getInfo();

    turbidity2 = turbidity2Result.get('B4').getInfo();
  } else {
    // Landsat 8
    img2 = col2.map(maskL8clouds).median();

    const turbidity2Result = img2.select('SR_B4').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: point,
      scale: 3000,
      maxPixels: 1e9
    });

    count2 = img2.select('SR_B4').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: point,
      scale: 3000,
      maxPixels: 1e9
    }).get('SR_B4').getInfo();

    turbidity2 = turbidity2Result.get('SR_B4').getInfo();
  }

  console.log(`2020 Valid pixels: ${count2}`);

  if (count2 === 0) {
    console.log("No valid pixels for 2020 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Validation & Final Answer
  console.log(`2015 Sediment proxy (Red reflectance): ${turbidity1}`);
  console.log(`2020 Sediment proxy (Red reflectance): ${turbidity2}`);

  if (turbidity1 === null || turbidity2 === null || 
      isNaN(turbidity1) || isNaN(turbidity2) ||
      turbidity1 < 0 || turbidity2 < 0 || 
      turbidity1 > 1 || turbidity2 > 1) {
    console.log("Invalid calculation results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (turbidity1 > turbidity2) {
    console.log("2015 had more sediment than 2020.");
    console.log("<answer>A</answer>");
  } else {
    console.log("2015 did not have more sediment than 2020.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
